arguments.command:
run_sql "
SELECT
    if(Origin='ATL', (CAST(left(CRSDepTime, 2) AS Int32) - 4) % 24,
    if(Origin='ORD', (CAST(left(CRSDepTime, 2) AS Int32) - 5) % 24,
    if(Origin='DFW', (CAST(left(CRSDepTime, 2) AS Int32) - 5) % 24,
    if(Origin='DEN', (CAST(left(CRSDepTime, 2) AS Int32) - 6) % 24,
    if(Origin='LAX', (CAST(left(CRSDepTime, 2) AS Int32) - 7) % 24, -1))))) as utc_hour,
    count() as dep_count
FROM aviation.flights
WHERE Origin IN ('ATL', 'ORD', 'DFW', 'DEN', 'LAX')
  AND Cancelled = 0
  AND length(CRSDepTime) >= 2
GROUP BY utc_hour
ORDER BY dep_count DESC
LIMIT 10
"
